SELECT 
    SUM(CASE WHEN RIAGENDR = 2 AND SLD012 < 7 THEN WTDRD1 ELSE 0 END) / SUM(WTDRD1) 
FROM survey;

SELECT 
    SUM(CASE WHEN DMDEDUC2 = 1 THEN DR1TCARB * WTDRD1 ELSE 0 END) / SUM(CASE WHEN DMDEDUC2 = 1 THEN WTDRD1 ELSE 0 END) 
FROM survey;

SELECT SUM(WBMXWAIST * WTINT2YR) / SUM(WTINT2YR) 
FROM survey 
WHERE RIDRETH1 = 2;

SELECT CORR(INDFMPIR, SLD012) AS corr_value FROM survey WHERE INDFMPIR IS NOT NULL AND SLD012 IS NOT NULL AND SEQN IN (
    SELECT SEQN FROM survey WHERE INDFMPIR IS NOT NULL AND SLD012 IS NOT NULL
) GROUP BY SEQN HAVING COUNT(*) > 1
